function pricingRows(g){const map=new Map();for(const item of g.variants){const key=pricingKey(item);let entry=map.get(key);if(!entry){entry={item,rows:[],conflict:false};map.set(key,entry);}entry.rows.push(item);if(Number(item.sale_price)!==Number(entry.item.sale_price))entry.conflict=true;}return [...map.values()];}
function compareSpecs(a,b){const x=specs(a),y=specs(b);for(const key of ['diameterCm','widthCm','heightCm','thicknessMm']){const diff=Number(x[key]||0)-Number(y[key]||0);if(diff)return diff;}return String(x.material||'').localeCompare(String(y.material||''),'fa')||String(a.id).localeCompare(String(b.id));}
function cardColors(g){const configured=g.variants.find(x=>Array.isArray(specs(x).modelColors))?.variant_specs.modelColors;return configured||[...new Set(g.variants.map(x=>specs(x).color))].sort((a,b)=>String(a).localeCompare(String(b),'fa'));}
function choose(g,id){const selected=g.variants.find(x=>String(x.id)===String(id));if(selected)return selected;const first=cardColors(g).find(color=>g.variants.some(x=>specs(x).color===color)),rows=g.variants.filter(x=>specs(x).color===first);return rows.sort(compareSpecs)[0]||g.variants[0];}
function changeChoice(g,current,key,value){let rows=g.variants;const material=current.variant_specs?.material||g.material;if(key==='material')rows=rows.filter(x=>(x.variant_specs?.material||g.material)===value);else rows=rows.filter(x=>(x.variant_specs?.material||g.material)===material);if(key==='color')rows=rows.filter(x=>x.variant_specs?.color===value);else if(key!=='material')rows=rows.filter(x=>x.variant_specs?.color===current.variant_specs?.color);if(key==='size')rows=rows.filter(x=>size(x)===value);else if(key==='thickness')rows=rows.filter(x=>size(x)===size(current)&&String(x.variant_specs?.thicknessMm??'')===value);return rows.find(x=>size(x)===size(current)&&String(x.variant_specs?.thicknessMm??'')===String(current.variant_specs?.thicknessMm??''))||rows.sort(compareSpecs)[0];}
function photo(item){return item?.color_image_urls?.[0]||item?.thumbnail_url||item?.thumbnail_urls?.[0]||item?.image_url||item?.image_urls?.[0]||item?.gallery_images?.find(x=>x.url)?.url||'';}
